async function recordGitHubDispatch(env) {
  if (!env.KV) return;
  try {
    await env.KV.put(
      GITHUB_DISPATCH_COOLDOWN_KEY,
      String(Date.now()),
      { expirationTtl: Math.ceil(GITHUB_DISPATCH_COOLDOWN_MS / 1000) + 60 }
    );
  } catch (e) {
    console.error("写入 dispatch 冷却失败（忽略）：", e);
  }
}

async function isGitHubDispatchCooldownActive(env) {
  if (!env.KV) return false;
  const raw = await env.KV.get(GITHUB_DISPATCH_COOLDOWN_KEY);
  if (!raw) return false;
  const last = parseInt(raw, 10);
  if (!Number.isFinite(last)) return false;
  return Date.now() - last < GITHUB_DISPATCH_COOLDOWN_MS;
}

function normalizeScheduleEntries(raw) {
  if (!raw) return [];
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    return [];
  }

  let entries = [];
  if (Array.isArray(data)) {
    entries = data;
  } else if (data && Array.isArray(data.entries)) {
    entries = data.entries;
  } else if (data && (data.trigger_at_ms || data.note)) {
    entries = [data];
  } else if (data && typeof data === "object") {
    for (const k of ["tenshi", "elaina"]) {
      if (data[k] && typeof data[k] === "object") entries.push(data[k]);
    }
  }

  const now = Date.now();
  const maxStale = 24 * 60 * 60 * 1000;

  return entries
    .map((e) => ({
      id: String((e && e.id) || ""),
      trigger_at_ms: Number((e && e.trigger_at_ms) || 0),
      note: String((e && e.note) || "").slice(0, 500),
    }))
    .filter((e) => e.trigger_at_ms > 0 && e.note)
    .filter((e) => now - e.trigger_at_ms < maxStale)
    .filter((e) => now - e.trigger_at_ms <= SCHEDULE_LATE_WINDOW_MS)
    .sort((a, b) => a.trigger_at_ms - b.trigger_at_ms);
}


function isScheduleDue(deltaMs) {
  return deltaMs <= SCHEDULE_EARLY_WINDOW_MS && deltaMs >= -SCHEDULE_LATE_WINDOW_MS;
}

async function writeScheduleKv(env, entries) {
  if (!env.KV) return;
  if (!entries || entries.length === 0) {
    await env.KV.delete(SCHEDULE_KV_KEY);
    return;
  }
  await env.KV.put(
    SCHEDULE_KV_KEY,
    JSON.stringify({ entries }),
    { expirationTtl: 86400 * 7 }
  );
}

function scheduleKvValue(entries) {
  return JSON.stringify({ entries });
}

async function writeScheduleKvIfChanged(env, entries, prevRaw) {
  if (!env.KV) return;
  if (!entries || entries.length === 0) {
    await env.KV.delete(SCHEDULE_KV_KEY);
    return;
  }
  const nextRaw = scheduleKvValue(entries);
  const prev = String(prevRaw ?? "").trim();
  if (prev === nextRaw) return;

  await env.KV.put(
    SCHEDULE_KV_KEY,
    nextRaw,
    { expirationTtl: 86400 * 7 }
  );
}

function extractScheduleSyncToken(request, env) {
  const expected = String(env.SCHEDULE_SYNC_SECRET || "").trim();
  if (!expected) return { ok: false, expected: "", got: "" };

  const auth = (request.headers.get("Authorization") || "").trim();
  let got = "";
  if (auth.toLowerCase().startsWith("bearer ")) {
    got = auth.slice(7).trim();
  }
  if (!got) {
    got = (request.headers.get("X-Schedule-Sync-Secret") || "").trim();
  }
  return { ok: got === expected, expected, got };
}

async function handleScheduleSync(request, env) {
  const authCheck = extractScheduleSyncToken(request, env);
  if (!authCheck.ok) {
    const body = {
      error: "Unauthorized",
      hint:
        "SCHEDULE_SYNC_SECRET 未配置或与请求不一致。请在 Worker 与 GitHub Secret 填同一纯 ASCII 值后重新 Deploy。",
      worker_has_secret: Boolean(authCheck.expected),
      token_length_got: authCheck.got.length,
      token_length_expected: authCheck.expected.length,
    };
    return new Response(JSON.stringify(body), {
      status: 401,
      headers: { "Content-Type": "application/json; charset=utf-8" },
    });
  }
  if (!env.KV) {
    return new Response("OK (No KV)", { status: 200 });
  }

  if (request.method === "DELETE") {
    await env.KV.delete(SCHEDULE_KV_KEY);
    return new Response("OK", { status: 200 });
  }

  let body = {};
  try {
    const text = await request.text();
    if (text && text.trim()) body = JSON.parse(text);
  } catch {
    return new Response("Bad JSON", { status: 400 });
  }

  const entries = normalizeScheduleEntries(JSON.stringify(body));
  await writeScheduleKv(env, entries);
  return new Response("OK", { status: 200 });
}

async function maybeDispatchScheduledPerception(env, ctx, eventType) {
  if (!env.KV) return false;
  const raw = await env.KV.get(SCHEDULE_KV_KEY);
  if (!raw) return false;

  let entries = normalizeScheduleEntries(raw);
  if (entries.length === 0) {
    await env.KV.delete(SCHEDULE_KV_KEY);
    return false;
  }

  const now = Date.now();
  let pruned = false;

  while (entries.length > 0) {
    const delta = entries[0].trigger_at_ms - now;
    if (delta >= -SCHEDULE_LATE_WINDOW_MS) break;
    console.log(
      `定时感知队首已过期超过 ${SCHEDULE_LATE_WINDOW_MS / 60000} 分钟，移除: ${entries[0].id}`
    );
    entries = entries.slice(1);
    pruned = true;
  }

  if (entries.length === 0) {
    await env.KV.delete(SCHEDULE_KV_KEY);
    return false;
  }

  const head = entries[0];
  const delta = head.trigger_at_ms - now;

  if (!isScheduleDue(delta)) {
    if (delta > SCHEDULE_EARLY_WINDOW_MS) {
      console.log(`定时感知未到窗口，剩余约 ${Math.round(delta / 60000)} 分钟`);
    }
    await writeScheduleKvIfChanged(env, entries, raw);
    return false;
  }

  console.log(
    `定时感知进入触发窗（-1~+15 分钟），推送 scheduled_force，队首 id=${head.id}`
  );
  const client_payload = {
    scheduled_force: true,
    trigger_at_ms: head.trigger_at_ms,
    schedule_id: head.id || "",
    note: head.note,
  };

  const remaining = entries.slice(1);
  await writeScheduleKv(env, remaining);

  ctx.waitUntil(dispatchPerceptionGitHub(env, eventType, client_payload));
  return true;
}

async function dispatchPerceptionGitHub(env, eventType, payload) {
  await enqueueLegacy(env, 'perception', payload || {});
  await recordGitHubDispatch(env);
}

const MSG_PREFIX = "msg_";
const MSG_TTL_SEC = 600;
const MSG_FLUSH_CURSOR_KEY = "msg_flush_cursor";
const MSG_CURSOR_TTL_SEC = 7 * 24 * 60 * 60;
const MSG_BATCH_DEFAULTS = {
  firstWaitMs: 1500, // 先等第一波：相册的几条 update 通常几百毫秒内到齐
  quietMs: 3000, // 最新一条之后安静这么久就派发
  maxWaitMs: 12000, // 从本请求开始最多等这么久，防止断断续续的小消息无限拖延
  pollMs: 1000,
};

function msgBatchConfig(env) {
  const num = (raw, fallback) => {
    const n = Number(raw);
    return Number.isFinite(n) && n > 0 ? n : fallback;
  };
  const e = env || {};
  return {
    firstWaitMs: num(e.MSG_BATCH_FIRST_WAIT_MS, MSG_BATCH_DEFAULTS.firstWaitMs),
    quietMs: num(e.MSG_BATCH_QUIET_MS, MSG_BATCH_DEFAULTS.quietMs),
    maxWaitMs: num(e.MSG_BATCH_MAX_WAIT_MS, MSG_BATCH_DEFAULTS.maxWaitMs),
    pollMs: num(e.MSG_BATCH_POLL_MS, MSG_BATCH_DEFAULTS.pollMs),
  };
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function makeMessageKey(msgId) {
  const ts = String(Date.now()).padStart(13, "0");
  const id = String(Number(msgId) || 0).padStart(12, "0");
  const rand = Math.random().toString(36).slice(2, 9);
  return `${MSG_PREFIX}${ts}_${id}_${rand}`;
}

function parseMessageKey(name) {
  if (typeof name !== "string" || !name.startsWith(MSG_PREFIX)) return null;
  const parts = name.slice(MSG_PREFIX.length).split("_");
  if (parts.length < 2) return null;
  const ts = Number(parts[0]);
  const msgId = Number(parts[1]);
  if (!Number.isFinite(ts) || !Number.isFinite(msgId)) return null;
  return { ts, msgId };
}

async function bufferIncomingMessage(env, client_payload) {
  try {
    const key = makeMessageKey(client_payload && client_payload.msg_id);
    await env.KV.put(key, JSON.stringify(client_payload), {
      expirationTtl: MSG_TTL_SEC,
    });
    return { key };
  } catch (e) {
    console.error("消息缓冲失败，退回即时转发：", e);
    return null;
  }
}

async function readFlushCursor(env) {
  try {
    const raw = await env.KV.get(MSG_FLUSH_CURSOR_KEY);
    const ts = Number(raw);
    return Number.isFinite(ts) && ts > 0 ? ts : 0;
  } catch (e) {
    console.error("读取合并游标失败，按无游标处理：", e);
    return 0;
  }
}

async function listBufferedMessages(env, cursorTs) {
  const items = [];
  let cursor = null;
  for (;;) {
    const page = await env.KV.list({ prefix: MSG_PREFIX, cursor });
    for (const k of (page && page.keys) || []) {
      const meta = parseMessageKey(k.name);
      if (meta && meta.ts > cursorTs) items.push({ key: k.name, ...meta });
    }
    if (!page || page.list_complete || !page.cursor) break;
    cursor = page.cursor;
  }
  items.sort((a, b) => a.ts - b.ts || a.msgId - b.msgId);
  return items;
}

async function waitForBatch(env, ownKey) {
  const cfg = msgBatchConfig(env);
  const start = Date.now();
  await sleep(cfg.firstWaitMs);

  for (;;) {
    const cursorTs = await readFlushCursor(env);
    const items = await listBufferedMessages(env, cursorTs);
    if (items.length === 0) return null;

    const newest = items[items.length - 1];
    if (newest.key !== ownKey) return null; // 有更新的一条，交给它

    const quietFor = Date.now() - newest.ts;
    if (quietFor >= cfg.quietMs || Date.now() - start >= cfg.maxWaitMs) return items;
    await sleep(cfg.pollMs);
  }
}

async function flushMessageBatch(env, ownKey, ownPayload) {
  try {
    const items = await waitForBatch(env, ownKey);
    if (!items || items.length === 0) return;

    const cursorTs = await readFlushCursor(env);
    const fresh = items.filter((item) => item.ts > cursorTs);
    if (!fresh.some((item) => item.key === ownKey)) {
      console.log(`本批已由更新的批次派发，本次跳过（${ownKey}）。`);
      return;
    }

    const payloads = [];
    for (const item of fresh) {
      const raw = await env.KV.get(item.key);
      if (!raw) continue;
      try {
        payloads.push(JSON.parse(raw));
      } catch (e) {
        console.error(`合并时跳过坏消息 JSON: ${item.key}`, e);
      }
    }
    if (payloads.length === 0) return;

    const merged = buildBatchPayload(payloads);
    if (!merged) return;

    await triggerGitHubImmediate(env, merged);
    try {
      await env.KV.put(MSG_FLUSH_CURSOR_KEY, String(fresh[fresh.length - 1].ts), {
        expirationTtl: MSG_CURSOR_TTL_SEC,
      });
    } catch (e) {
      console.error("推进合并游标失败（消息已派发，忽略）：", e);
    }
    console.log(`合并派发 ${payloads.length} 条消息（msg_id ${merged.msg_id}）。`);
  } catch (e) {
    console.error("合并派发失败，退回即时转发本条：", e);
    try {
      await triggerGitHubImmediate(env, ownPayload);
    } catch (e2) {
      console.error("合并失败后的即时转发也失败：", e2);
    }
  }
}

function buildBatchPayload(messages) {
  const list = (Array.isArray(messages) ? messages : []).filter(
    (m) => m && typeof m === "object"
  );
  if (list.length === 0) return null;

  const sorted = [...list].sort(
    (a, b) => (Number(a.date) || 0) - (Number(b.date) || 0) || (Number(a.msg_id) || 0) - (Number(b.msg_id) || 0)
  );

  const texts = [];
  const files = [];
  const seenFileIds = new Set();
  let location = null;
  let replyTo = null;

  const addFile = (spec) => {
    if (!spec || typeof spec !== "object" || !spec.file_id) return;
    const fileId = String(spec.file_id);
    if (seenFileIds.has(fileId)) return;
    seenFileIds.add(fileId);
    files.push({
      file_id: fileId,
      file_type: spec.file_type || "file",
      file_name: spec.file_name || "file.bin",
    });
  };

  for (const m of sorted) {
    const text = typeof m.text === "string" ? m.text.trim() : "";
    if (text) texts.push(text);

    if (Array.isArray(m.file_ids)) {
      for (const f of m.file_ids) addFile(f);
    }
    if (m.file_id) {
      addFile({ file_id: m.file_id, file_type: m.file_type, file_name: m.file_name });
    }
    if (m.location && typeof m.location === "object") location = m.location;
    if (m.reply_to && typeof m.reply_to === "object") replyTo = m.reply_to;
  }

  const first = sorted[0];
  const last = sorted[sorted.length - 1];
  const pick = (field) =>
    last[field] !== undefined && last[field] !== null ? last[field] : first[field];

  const payload = {
    chat_id: pick("chat_id"),
    user_id: pick("user_id"),
    msg_id: pick("msg_id"),
    date: pick("date"),
  };

  if (texts.length > 0) payload.text = texts.join("\n\n");

  if (files.length === 1) {
    payload.file_id = files[0].file_id;
    payload.file_type = files[0].file_type;
    payload.file_name = files[0].file_name;
  } else if (files.length > 1) {
    payload.file_ids = files;
  }

  if (location) payload.location = location;
  if (replyTo) payload.reply_to = replyTo;

  if (!payload.text && !payload.file_id && !payload.file_ids && !payload.location) {
    return null;
  }
  return payload;
}

async function triggerGitHubImmediate(env, payload) {
  await enqueueLegacy(env, 'reply', payload);
  await recordGitHubDispatch(env);
}

function extractReplyTo(message) {
  const MAX_REPLY_TEXT = 1500;
  const MAX_QUOTE_TEXT = 500;
  const MEDIA_FIELDS = [
    "photo",
    "document",
    "voice",
    "audio",
    "sticker",
    "video",
    "video_note",
    "animation"
  ];

  const isObject = (v) => v !== null && typeof v === "object";
  const asNumber = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  };
  const asText = (v, max) => {
    if (typeof v === "string") return v.slice(0, max);
    if (typeof v === "number" || typeof v === "boolean") return String(v).slice(0, max);
    return "";
  };

  try {
    const msg = isObject(message) ? message : {};
    const reply = isObject(msg.reply_to_message) ? msg.reply_to_message : null;
    const quote = isObject(msg.quote) ? msg.quote : null;

    if (!reply && !quote) return null;

    const replyFrom = reply && isObject(reply.from) ? reply.from : {};

    let mediaType = "";
    if (reply) {
      for (const field of MEDIA_FIELDS) {
        if (reply[field]) {
          mediaType = field;
          break;
        }
      }
    }

    return {
      message_id: reply ? asNumber(reply.message_id) : 0,
      from_id: asNumber(replyFrom.id),
      from_is_bot: Boolean(replyFrom.is_bot),
      date: reply ? asNumber(reply.date) : 0,
      text: reply ? asText(reply.text || reply.caption, MAX_REPLY_TEXT) : "",
      quote_text: quote ? asText(quote.text, MAX_QUOTE_TEXT) : "",
      has_media: Boolean(mediaType),
      media_type: mediaType
    };
  } catch (e) {
    console.error("extractReplyTo failed:", e);
    return null;
  }
}
function deploymentBindings(env) {
  return {
    ...env,
    DATA_REPOSITORY: env.DATA_REPOSITORY || env.GH_REPO,
    DATA_BRANCH: env.DATA_BRANCH || 'main',
    DATA_TOKEN: env.DATA_TOKEN || env.GH_TOKEN,
    DISPATCH_TOKEN: env.DISPATCH_TOKEN || env.CALLING_GH_TOKEN || env['CALLING_GH_TOKEN '] || env.GH_TOKEN,
    SCHEDULE_SYNC_SECRET: env.SCHEDULE_SYNC_SECRET || env.PERCEPTION_SCHEDULE_SYNC_SECRET,
  };
}

async function controlRequest(request, env, path) {
  if (!extractScheduleSyncToken(request, env).ok) return new Response('Forbidden', {status: 403});
  if (request.method !== 'POST') return new Response('POST required', {status: 405});
  if (path === '/internal/probe') {
    const raw = await request.text();
    if (raw.length > 2048) return new Response('Too large', {status: 413});
    const nonce = JSON.parse(raw || '{}').nonce;
    if (typeof nonce !== 'string' || !/^[a-zA-Z0-9_-]{1,100}$/.test(nonce)) return new Response('Invalid nonce', {status: 400});
    const id = await enqueueLegacy(env, 'probe', {probe_nonce: nonce});
    return Response.json({event_id: id, task: 'probe'}, {status: 202});
  }
  if (!env.KV) return Response.json({queued: 0, event_id: null, scheduled_queued: 0});
  const cursor = await readFlushCursor(env);
  const items = await listBufferedMessages(env, cursor);
  const payloads = [];
  for (const item of items) {
    const raw = await env.KV.get(item.key);
    if (raw) payloads.push(JSON.parse(raw));
  }
  const merged = buildBatchPayload(payloads);
  let id = null;
  if (merged) {
    id = await enqueueLegacy(env, 'reply', merged);
    await env.KV.put(MSG_FLUSH_CURSOR_KEY, String(items[items.length - 1].ts), {expirationTtl: MSG_CURSOR_TTL_SEC});
  }
  let schedules = normalizeScheduleEntries(await env.KV.get(SCHEDULE_KV_KEY));
  let scheduledQueued = 0;
  while (schedules.length && schedules[0].trigger_at_ms <= Date.now() + SCHEDULE_EARLY_WINDOW_MS) {
    const head = schedules[0];
    await enqueueLegacy(env, 'perception', {scheduled_force: true, trigger_at_ms: head.trigger_at_ms, schedule_id: head.id || '', note: head.note});
    schedules = schedules.slice(1);
    await writeScheduleKv(env, schedules);
    scheduledQueued++;
  }
  return Response.json({queued: merged ? payloads.length : 0, event_id: id, scheduled_queued: scheduledQueued});
}

export default {
  async fetch(request, env, ctx) {
    env = deploymentBindings(env);
    const url = new URL(request.url);
    if (url.pathname === '/health' && request.method === 'GET') return Response.json({service: 'rp-core', protocol: 'rp/1', enabled: env.RP_LIVE_ENABLED === 'true'});
    if (['/internal/probe', '/internal/drain-inbox'].includes(url.pathname)) {
      try { return await controlRequest(request, env, url.pathname); }
      catch { return new Response('Control operation unavailable', {status: 503}); }
    }
    if (env.RP_LIVE_ENABLED !== 'true') return new Response('Disabled', {status: 503});
    const internal = url.pathname === '/internal/perception-schedule';
    if (!internal && !timingSafeEqual(request.headers.get(TELEGRAM_WEBHOOK_SECRET_HEADER) || '', env.TELEGRAM_WEBHOOK_SECRET || '')) return new Response('Forbidden', {status: 403});
    try {
      const { identity } = await bindings(env);
      const id = identity.allowed_user_ids?.[0];
      if (id === undefined) return new Response('Not configured', {status: 503});
      return await runtime.fetch(request, {...env, ADMIN_ID: String(id)}, ctx);
    } catch {
      return new Response('Ingress unavailable', {status: 503});
    }
  },
  async scheduled(event, env, ctx) {
    env = deploymentBindings(env);
    if (env.RP_LIVE_ENABLED !== 'true') return;
    return runtime.scheduled(event, env, ctx);
  }
};
